import { writeFileSync } from 'node:fs';

const CINE =
	' CINEMATOGRAPHY (character intro-card look): three depth planes, always. A dark, soft, out-of-focus foreground shape right at the lens (FG). The subject razor-sharp in the midground. The background melting into atmospheric haze and big creamy round bokeh discs from small real lights. Shallow depth of field, anamorphic lens feel, rack focus, haze between the planes, a hard key that models the faces and a thin edge light separating them from the background. Never flat, never every plane in equal focus.';
const LEGEND =
	'LEGEND VARIANT (the story as the city believes it, told as real): same painted webtoon look, but a slightly heightened folk-tale register, cooler moon-blue palette, drifting silver mist and floating lantern motes. The dokkaebi are truly supernatural, not costumes. ';
const SPIRITS = ['/ch_rascals_spirit.png', '/ch_old_man_tree_spirit.png', '/ch_rock_lady_spirit.png'];
const HUMANS = ['/ch_rascals.png', '/ch_old_man_tree.png', '/ch_rock_lady.png'];
const YOUNG = { yongsu: 'static/ch_bihyung.png', chunmyung: 'static/ch_chunmyung_young.png' };

const items = [
	// Chunmyung & Yongsu — real
	['bh-garden-meet', 'Bihyung', 601, 'She doesn’t laugh. Then she very nearly does', 'In the palace garden Chunmyung refuses to laugh at the madman, and very nearly does.', 'Close two-shot in the palace garden at golden hour. FG: blurred plum blossoms. Princess Chunmyung, seventeen, in Sacred Bone silk with her binyeo, arms folded, lips pressed tight against a laugh she is losing. Bihyung (one stray strand of hair poking up from his careless topknot) bows far too low, peeking up at her with a crooked grin. Background: pavilion roofs and a pond dissolving into golden bokeh.', ['chunmyung', 'yongsu'], 'day'],
	['bh-bridge-laugh', 'Bihyung', 601, 'Once she makes him laugh on the beat instead of after it.', 'On the bridge after the temple bell, she makes him laugh on the beat for the first time.', 'Tight close-up two-shot on the Ghost Bridge at night, faces filling the frame. FG: the out-of-focus flame of the lamp she brought. Bihyung caught mid-laugh, genuinely surprised at himself, eyes creased; Chunmyung beside him, shoulder to shoulder, staring at him, startled and delighted. Background: black water and the temple roof melting into warm bokeh discs. Intimate, tender.', ['yongsu', 'chunmyung'], 'night'],
	['bh-cold-feet', 'Bihyung', 601, 'Then it’s unanimous. Say yes.', 'Then it’s unanimous. Say yes. My feet are cold.', 'Low close shot on the bridge stones at night. FG: her bare feet on the cold wet stone, soft focus. Chunmyung grips Bihyung by the collar, nose to nose, fierce and blushing, giving him an order; he looks at her, helpless, the madness gone out of his face. His coat is already half off his shoulders to put over her feet. One lamp on the stones below rakes up both faces; bokeh of reflected light in the water behind.', ['chunmyung', 'yongsu'], 'night'],
	['bh-stream-wedding', 'Bihyung', 602, 'The wedding is small, at the house by the stream.', 'A small wedding at the house by the stream; seven-year-old Dukman brought a radish.', 'Medium shot at a small wedding in the yard of a modest house by a stream, spring dusk. FG: a blurred paper lantern and plum branch. Chunmyung and Bihyung in simple wedding silk bow to each other over a low table, both trying not to laugh. Off to one side, tiny and sharp, a seven-year-old girl in silk holding up a radish as her gift. Background: the stream and a crooked stone bridge dissolving into lantern bokeh.', ['chunmyung', 'yongsu'], 'night'],
	['bh-hand-mouth', 'Bihyung', 602, 'She puts her hand over his mouth.', 'The first night in the house by the stream, she puts her hand over his mouth.', 'Intimate close-up on the first night, lamp low beside a sleeping mat. FG: the soft blurred edge of a silk quilt. Bihyung, hair loose, starts to talk to the rafters; Chunmyung, hair down with her binyeo out, leans over him and lays her hand over his mouth, smiling. His eyes go from the ceiling to her. Warm lamp rakes across both faces; the room falls to umber black with a few ember bokeh. Romantic, quiet, clothed.', ['chunmyung', 'yongsu'], 'night'],
	['bh-deathbed-hands', 'Bihyung', 653, 'They are buried on the same day, on the hill west of the stream', 'Old Yongsu and Chunmyung die in the same bed, holding hands, looking into each other’s eyes.', 'Very romantic intimate close-up. Two very old people lie facing each other on one sleeping mat in the house by the stream, white hair loose on the pillows, wrinkled faces close together, holding hands between them, looking into each other’s eyes with soft smiles, at peace. Yongsu (still the one stray strand of hair) and Chunmyung, aged seventy. FG: a blurred guttering lamp on the floor. A shaft of pale dawn from a lattice window crosses their joined hands. Background: plum blossoms outside the window dissolving into soft bokeh. Tender, warm, not morbid.', ['yongsu', 'chunmyung'], 'day'],
	// Chunmyung & Yongsu — legend
	['bh-myth-lantern-bridge', 'Bihyung', 601, 'He comes back the next night. So does she.', 'Legend: the goblins hold up their lanterns over the bridge so the princess can find her madman.', LEGEND + 'Night on the Ghost Bridge. Chunmyung in Sacred Bone silk walks out onto the bridge toward Bihyung, who waits in the middle. All around them, the dokkaebi from the boards (three masked smoke-haired rascal goblins, Old Man Tree with his hollow wooden face, the Rock Lady with her stone face and boulder crown) hang over the parapets and stand in the water, holding up paper lanterns to light her way, grinning. FG: a goblin’s blurred lantern right at the lens. Background: lantern bokeh on the water.', ['chunmyung', 'yongsu'], 'night', SPIRITS],
	['bh-myth-wedding-wall', 'Bihyung', 602, 'It is the only room in Surabol where he never once performs.', 'Legend: the goblins of Surabol peer over the wall on the wedding night.', LEGEND + 'Over a yard wall at night, from behind: the dokkaebi from the boards (three masked smoke-haired rascals, Old Man Tree, Rock Lady) crowd on top of the wall, peeking toward the single warm lit window of the house by the stream, shushing each other, delighted. FG: the out-of-focus roof tiles of the wall and a goblin’s smoke hair. In the window, small and soft, two silhouettes close together. Background: stream mist, moon and lantern bokeh.', [], 'night', SPIRITS],
	['bh-myth-parents-bridge', 'Bihyung', 653, 'He stands on it for a long time.', 'Legend: after the burial, Chunchu stands on the Ghost Bridge as his young parents walk away across it.', LEGEND + 'Evening on the crooked Ghost Bridge. Kim Chunchu, a grown man in mourning white, stands alone on the bridge looking down at the water. Behind him, translucent only in the mist, his parents young again (Bihyung with his stray strand, Chunmyung at seventeen) walk away hand in hand across the far end of the bridge, glancing back at him, smiling; the goblins wait for them on the far bank with lanterns. FG: blurred reeds. Background: mist and lantern bokeh.', ['chunchu', 'yongsu', 'chunmyung'], 'night', SPIRITS, YOUNG],
	// Gildal
	['bh-gildal-roof', 'Bihyung', 603, 'Some nights the madman climbs the gate tower', 'Bihyung and Gildal sit on the gate-tower roof with their legs over the edge.', 'Night, high on the curved tiled roof of a gate tower. FG: blurred roof-ridge ornament at the lens. Bihyung (stray strand of hair) and Gildal (orange robe, red hood, fox mask pushed up on his head) sit side by side with their legs over the edge, sharing a jar, laughing. Far below, the sleeping city of Surabol dissolves into a sea of tiny lamp bokeh under the moon. Friendship.', ['yongsu', 'gildal'], 'night'],
	['bh-gildal-waiting', 'Bihyung', 603, 'I’ll wait as long as you like. I have never once been late.', 'Gildal: I have never once been late.', 'Emotional close-up of Gildal at dusk under the gate tower, fox mask pushed up on his head, eyes wet, a loyal tired smile. FG: the blurred shoulder and stray hair strand of Bihyung, back to camera. Background: a lamp-lit gate dissolving into bokeh.', ['gildal', 'yongsu'], 'night'],
	['bh-myth-gildal-death', 'Bihyung', 603, 'that night the goblins bring it back to him, and kill it.', 'Legend: the goblins drag the fox back to the reeds; Bihyung stands over it with white eyes.', LEGEND + 'Night in the reeds. The dokkaebi from the boards (three masked smoke-haired rascals, Old Man Tree with root hands, the Rock Lady) drag a struggling orange-robed fox-goblin back by the tail and arms. Bihyung (stray strand, eyes gone SOLID WHITE) stands over them, face set, grief held in. FG: blurred reeds and a goblin’s lantern. Background: moon mist and bokeh.', ['yongsu'], 'night', ['/ch_gildal_dokebi.png', ...SPIRITS]],
	['bh-gildal-death-real', 'Bihyung', 603, '…He was your friend.', 'The reality: on the south road at night, the orphan boys and the old stonecutter stand over Gildal, his fox mask cracked in the mud.', 'Night on the south road, torchlight. FG: a blurred torch flame and the cracked fox mask lying in the mud. Gildal, the man in the orange robe and red hood, lies dead in the road. Around him, copied exactly from the boards: three orphan boys with their goblin masks round their necks, faces frightened and wet, and the one-eyed old stonecutter with his white beard leaning on his staff. A step back, Bihyung (stray strand of hair) turns his face away. Background: dark pines and ember bokeh.', ['gildal', 'yongsu'], 'night', HUMANS],
	['bh-he-was-late', 'Bihyung', 603, 'He was late. / First time ever.', 'He was late. First time ever.', 'Emotional close two-shot in a doorway at grey dawn. FG: Chunmyung’s blurred shoulder and binyeo. Bihyung, muddy to the knees, eyes red, says it with a crooked, broken smile. Chunmyung’s face, sharp in profile, hurt and furious and holding back tears. Background: the stream and the bridge melting into pale mist bokeh.', ['yongsu', 'chunmyung'], 'day'],
	// Suulbu
	['bh-suulbu-supper', 'Bihyung', 592, 'three people eat supper at a table built for twelve', 'Three people eat supper at Prince Suulbu’s table for twelve.', 'Long low shot down a huge empty lacquered table built for twelve, lamps along it. FG: blurred silver dishes at the lens. At the far end, Prince Suulbu (High Councillor) sits upright in fine silk, cold and composed, speaking without looking up; his young daughter Manmyung beside him, eyes down, fists in her lap. Background: dark screens and lamp bokeh. Power and loneliness.', ['sukhuljong', 'manmyung'], 'night'],
	['bh-suulbu-garden', 'Bihyung', 601, 'Nobody at those banquets could ever make the months add up.', 'King Jinpyung turns Suulbu’s threat back on him in the garden.', 'Tense close two-shot in the palace garden. FG: blurred pine needles. Prince Suulbu stands, a tall older lord in fine court silk and black feather cap, mouth open with nothing coming out, the only time anyone sees him lose a sentence. King Jinpyung, in his gold crown, sits relaxed on a garden bench, smiling thinly up at him. Background: pavilions dissolving into cool haze and bokeh.', ['sukhuljong', 'jinpyung'], 'day'],
	['bh-suulbu-chair', 'Bihyung', 625, '…You were never mad. Were you.', 'At the wedding door, ninety-year-old Suulbu stops his chair: you were never mad. Were you.', 'Close two-shot at a doorway at night. FG: the blurred carved arm of a sedan chair. Prince Suulbu, ninety, shrunken in fine silk in his carried chair, leans out and studies Yongsu with sharp old eyes. Yongsu, grey now in his late forties, a crooked half-smile, the one stray strand of hair still poking up, says nothing. Background: wedding lanterns and musicians melting into warm bokeh.', ['sukhuljong', 'yongsu'], 'night'],
	// Muryuk — Golden Gaya & Great Gaya
	['mur-ford', 'Muryuk', 532, 'Hold the ford. HOLD it, I said.', 'Muryuk holds the ford while his father climbs the hill to surrender.', 'Battle at a river ford, mid-moment, Golden Gaya burning behind. FG: a blurred Silla spear tip and spray. Muryuk, in steel lamellar and tall conical Gaya helm with purple cloth, shouting, ring-pommel sword raised, holding the ford in knee-deep water with his father’s guard behind him. Behind, small on the hill road, his father King Guhae turns away up the slope. Background: smoke columns off iron sheds and ember bokeh.', ['muryuk', 'guhae'], 'day', [], null, { battle: true, action: true }],
	['mur-face-front', 'Muryuk', 532, 'Face front, Muryuk.', 'In the Silla throne hall, Guhae tells his son to face front.', 'Over-the-shoulder close shot in the Silla throne hall. FG: blurred shoulder of a Silla guard. Kim Guhae, the surrendered king, stands before King Beopheung’s dais with his sons, murmuring sideways without turning his head. Muryuk beside him, jaw tight, eyes wet, looking back over his shoulder toward the doors. Background: Beopheung on his dais and the red pillars dissolving into lamp bokeh.', ['guhae', 'muryuk', 'beopheung'], 'day'],
	['mur-guhae-smiths', 'Muryuk', 533, 'There’s no Majesty in this house.', 'Guhae lifts the kneeling harbour smiths out of the wet lane: there’s no Majesty in this house.', 'Rainy lane in Surabol at dusk. FG: a blurred dripping eave. Kim Guhae in plain robes bends to lift a soot-blackened Gaya smith up out of the mud by the elbows; three more smiths kneel behind, faces pleading. In the doorway behind, young-adult Muryuk watches, fists tight. Background: wet giwa roofs and lamp bokeh in the rain.', ['guhae', 'muryuk'], 'day'],
	['mur-iron-seller', 'Muryuk', 534, 'Kim Guhae walks past them every morning', 'Every morning Guhae walks past the jeering men without turning his head; Muryuk turns his every time.', 'Morning lane, low angle. FG: blurred jeering men on the left, mouths open. Kim Guhae walks straight past, eyes front, calm. A step behind him, Muryuk turns his head to stare the hecklers down, burning. Background: the Moon Palace hill in morning haze and dust bokeh.', ['guhae', 'muryuk'], 'day'],
	['mur-bareheaded', 'Muryuk', 562, 'He walks up the gate road bareheaded, the helm in his hand.', 'At Great Gaya, Muryuk walks up the gate road bareheaded, the helm in his hand, every bow on the wall on him.', 'Worm’s-eye up the gate road of Great Gaya. FG: a blurred Gaya arrow stuck in the dirt. Muryuk, a hardened grey-streaked general in steel lamellar, bareheaded, tall conical Gaya helm in his hand, walks alone up toward the gate. On the wall above, a row of Gaya archers in the same cone helms draw on him. Background: the gate tower and a storm sky with one break of light, smoke bokeh.', ['muryuk'], 'day', [], null, { battle: true }],
	['mur-great-gaya-streets', 'Muryuk', 562, 'Inside the walls the fighting is short and mean', 'Inside Great Gaya the fighting is short and mean, street by street.', 'Street fight inside Great Gaya, mid-moment. FG: a blurred falling shield and sparks. Muryuk, in steel lamellar and cone helm, sword raised, drives through a burning street against Gaya defenders in identical helms; his own face torn between fury and grief. Silla blue soldiers behind him. Background: burning thatch and ember bokeh.', ['muryuk'], 'day', [], null, { battle: true, action: true }],
	['mur-old-lords', 'Muryuk', 562, 'He finds the old lords of Great Gaya in the hall', 'Muryuk finds the old lords of Great Gaya in the hall, sitting very straight.', 'Interior hall of Great Gaya. FG: blurred broken door timber. Muryuk stands in the doorway, helm under his arm, bloody. Before him, the old lords of Great Gaya sit very straight in a row on the floor in their best silk, waiting to die, one ancient lord looking him in the eye. Smoke drifts through a shaft of light; background dissolves into dusty bokeh.', ['muryuk'], 'day', [], null, { battle: true }],
	['mur-knot', 'Muryuk', 562, 'Then he goes back to the knot.', 'The boy-general Sadaham cuts his prisoners free, knot by knot; Muryuk watches.', 'The square below the hall of Great Gaya. FG: blurred rope across the lens. Sadaham, fifteen, in steel lamellar with ice-blue cloth, kneels to untie a roped Gaya prisoner, absorbed. Behind him, Muryuk, older, stands motionless watching, face unreadable. A long line of roped prisoners recedes into smoke and bokeh.', ['sadaham', 'muryuk'], 'day', [], null, { battle: true }]
];

const out = items.map(([id, entry, year, at, alt, scene, people, time, refs, faces, extra]) => ({
	id,
	entry,
	year,
	at,
	alt,
	scene: scene + CINE,
	...(people.length ? { people } : {}),
	...(refs?.length ? { refs, refsNote: refs === HUMANS ? 'the real people behind the goblin legend: copy each exactly' : 'dokkaebi designs: copy each exactly' } : {}),
	...(faces ? { faces } : {}),
	time,
	...(extra ?? {})
}));
writeFileSync(new URL('./scenes-bihyung2.json', import.meta.url), JSON.stringify(out, null, '\t') + '\n');
console.log(out.length);
